template <typename T>
SharedPointer<T> &SharedPointer<T>::operator=(const SharedPointer<T> &other) noexcept
{
    CopyNSwap(other);
    return (*this);
}

template <typename T>
T &SharedPointer<T>::operator*() const
{
    return (*m_pointer);
}

template <typename T>
T *SharedPointer<T>::operator->() const
{
    return (m_pointer);
}

template <typename T>
