{
    return (m_pointer);
}

template <typename T>
void SharedPointer<T>::Swap(SharedPointer<T> &cpy)
{
    std::size_t *tmp_counter = m_counter;
    m_counter = cpy.m_counter;
    cpy.m_counter = tmp_counter;

    T *tmp_pointer = m_pointer;
    m_pointer = cpy.m_pointer;
    cpy.m_pointer = tmp_pointer;
}

template <typename T>
void SharedPointer<T>::CopyNSwap(const SharedPointer<T> &other)
{
    SharedPointer<T> cpy(other);
    Swap(cpy);
}

template <typename T>
std::size_t *SharedPointer<T>::SetCounter(void)
{
    try
    {
        m_counter = new std::size_t(1);
    }
    catch(const std::bad_alloc& b)
    {
        DeleteResources();
        throw(b);
    }

    return (m_counter);
}

template <typename T>
bool SharedPointer<T>::IsShared(void)
{
    return (0 != *m_counter);
}

template <typename T>
void SharedPointer<T>::DecCounter(void)
{
    --(*m_counter);
}

template <typename T>
void SharedPointer<T>::IncCounter(void)
{
    ++(*m_counter);
}

template <typename T>
void SharedPointer<T>::Deallocate(void)
{
    DecCounter();
    if(!IsShared())
    {
        DeleteResources();
    }
}

template <typename T>
void SharedPointer<T>::DeleteResources(void)
{
    delete (m_pointer);
    m_pointer = nullptr;
    delete (m_counter);
    m_counter = nullptr;
}

RCString& RCString::operator=(const RCString& other_)
{
    if(this != &other_)
    {
        ReleaseData();
        m_data = other_.m_data;
        ++(m_data->counter);
    }

    return (*this);
}

size_t RCString::Length() const
{
    return (std::strlen(m_data->str));
}

bool RCString::IsShared() const
{
    return (m_data->counter > 1);
}

const char *RCString::ToCstr() const
{
    return (m_data->str);
